const brief180={explore:['CONOCE CADA PIEZA','Explora la flota','Del exterior al último componente. Elige un tren, gira el modelo y descubre su construcción.','Entrar al taller'],maintenance:['TU PRÓXIMA INTERVENCIÓN','Resuelve la falla','Busca tus herramientas, trabaja sobre el tren y comprueba cada reparación.','Comenzar una misión'],operator:['TU LUGAR ES LA CABINA','Toma los mandos','Controla la tracción, prepara la parada y lleva a tus pasajeros hasta la siguiente estación.','Entrar en cabina'],automatic:['LA CIUDAD EN MOVIMIENTO','Recorre la red','Sigue un convoy o recorre el andén a pie para observar la operación desde otra perspectiva.','Observar la red'],substations:['DE LA ENERGÍA AL MOVIMIENTO','Entra a la subestación','Recorre los equipos, abre sus gabinetes y completa una intervención guiada por su lista de trabajo.','Explorar subestaciones']};
export function mountHome180(doc=document){const home=doc.getElementById('game-home'),buttons=[...doc.querySelectorAll('[data-game-mode]')];if(!home||buttons.length!==5||doc.getElementById('home180'))return false;const root=doc.createElement('div');root.id='home180';root.innerHTML='<header><a href="#game-home-title" aria-label="MetroLab inicio"><span>M</span><strong>METROLAB<small>CIUDAD DE MÉXICO</small></strong></a><p>EXPERIENCIA FERROVIARIA <b>01 / 08</b></p></header><div class="home180-layout"><section class="home180-select"><small>ELIGE TU PRÓXIMO TURNO</small><nav id="game-home-menu" aria-label="Modos de juego"></nav><div class="home180-utils"><button type="button" data-home180-info>Biblioteca</button><button type="button" data-home180-settings>Ajustes</button></div></section><section class="home180-hero"><span data-home180-tag></span><h1 id="game-home-title" tabindex="-1">Toma los mandos</h1><p data-home180-description></p><button type="button" data-home180-start><span></span><b aria-hidden="true">→</b></button><div class="home180-lines"><span><b>1</b> NM-22</span><span><b>8</b> NM-79 · MP-82</span></div></section></div><footer><span>EXPLORA. COMPRENDE. OPERA.</span><span>↑ ↓ Elegir modo · Entrar para comenzar</span></footer>';
 const old=[...home.children];home.append(root);let selected='operator';const nav=root.querySelector('nav');const preview=id=>{selected=id;const [tag,title,text,action]=brief180[id];root.dataset.mode=id;root.querySelector('[data-home180-tag]').textContent=tag;root.querySelector('#game-home-title').textContent=title;root.querySelector('[data-home180-description]').textContent=text;root.querySelector('[data-home180-start]').querySelector('span').textContent=action;for(const b of buttons)b.setAttribute('data-selected180',String(b.dataset.gameMode===id));};for(const b of buttons){nav.append(b);b.addEventListener('pointerenter',()=>preview(b.dataset.gameMode));b.addEventListener('focus',()=>preview(b.dataset.gameMode));}for(const n of old)n.remove();root.querySelector('[data-home180-start]').onclick=()=>buttons.find(b=>b.dataset.gameMode===selected).click();root.querySelector('[data-home180-info]').onclick=()=>doc.getElementById('documents-open').click();root.querySelector('[data-home180-settings]').onclick=()=>globalThis.window?.metroGameShell105?.openSettings();root.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','Enter'].includes(e.key)||e.target.tagName==='BUTTON'&&e.key==='Enter')return;e.preventDefault();const i=buttons.findIndex(b=>b.dataset.gameMode===selected);if(e.key==='Enter')buttons[i].click();else buttons[(i+(e.key==='ArrowDown'?1:4))%5].focus();});preview(selected);return true;}
if(typeof document!=='undefined'){if(!mountHome180()){const obs=new MutationObserver(()=>{if(mountHome180())obs.disconnect();});obs.observe(document.body,{childList:true,subtree:true});}}
